import json
import datetime


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def audit(slug, action, target, summary, workq_item_id=None):
    if not slug:
        return
    today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
    path = "PracticeManager/AuditLog/" + slug + "-" + today + ".jsonl"
    try:
        existing = api.files.read(file=path)
    except Exception:
        existing = ""
    entry = {
        "ts": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "practice_slug": slug,
        "actor": "agent",
        "source": "automation:Form-chase reminder",
        "action": action,
        "target": target,
        "summary": summary,
    }
    if workq_item_id:
        entry["workq_item_id"] = workq_item_id
    line = json.dumps(entry, sort_keys=True)
    api.files.put(file=path, content=(existing + line + "\n") if existing else (line + "\n"))


tomorrow = (datetime.datetime.utcnow() + datetime.timedelta(days=1)).strftime("%Y-%m-%d")

entries = []
try:
    entries = api.files.list(path="PracticeManager/EnquiryThreads", scope="org")
except Exception:
    entries = []

chased = 0
checked = 0
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    todo_id = str(fname)[:-5]
    thread = read_json("PracticeManager/EnquiryThreads/" + fname, {}) or {}
    if not thread or thread.get("status") != "booked":
        continue
    if thread.get("form_complete") or thread.get("form_chased"):
        # Never chase the same patient twice, and never chase once the form is known complete.
        continue
    starts_at = str(thread.get("appointment_starts_at") or "")
    if not starts_at[:10] == tomorrow:
        continue
    patient_form_id = thread.get("patient_form_id") or ""
    if not patient_form_id:
        continue

    checked += 1
    try:
        pf = api.connectors.invoke(server="cliniko-clinical", tool="get_patient_form", args={"id": patient_form_id})
    except Exception:
        pf = None
    pf = pf if isinstance(pf, dict) else {}
    completed_at = pf.get("completed_at")
    form_url = str(pf.get("url") or "")

    if completed_at:
        thread["form_complete"] = True
        write_json("PracticeManager/EnquiryThreads/" + fname, thread)
        continue

    enquirer_email = thread.get("enquirer_email") or ""
    enquirer_name = thread.get("enquirer_name") or "there"
    if enquirer_email:
        body = (
            "Hi " + enquirer_name + ", just a reminder that your appointment is tomorrow (" + starts_at + "). "
            + ("Please complete your intake form before your visit: " + form_url if form_url else "Please complete your intake form before your visit.")
        )
        try:
            api.connectors.invoke(
                server="m365-mail-send", tool="send_email",
                args={"to": [enquirer_email], "subject": "Reminder: please complete your intake form", "body": body, "contentType": "Text"},
            )
            thread["form_chased"] = True
            write_json("PracticeManager/EnquiryThreads/" + fname, thread)
            audit(thread.get("slug") or "", "sent", {"kind": "email", "id": enquirer_email}, "Chased " + enquirer_name + " for an incomplete intake form", todo_id)
            chased += 1
        except Exception:
            pass

checked_count = checked
chased_count = chased
